function buildCandles(
  symbol: string,
  timeframe: Timeframe,
  rows: [string, string, number, number, number, number, number][],
): Candle[] {
  return rows.map(([openTime, closeTime, open, high, low, close, volume]) => ({
    symbol,
    timeframe,
    openTime: new Date(openTime),
    closeTime: new Date(closeTime),
    open,
    high,
    low,
    close,
    volume,
    closed: true,
  }));
}
